_UNITS = {"s": 1, "m": 60, "h": 3600, "d": 86400}
_UNIT_ORDER = {"d": 3, "h": 2, "m": 1, "s": 0}


def parse_duration(text: str) -> int:
    """Parse a duration string such as ``90s`` or ``1h30m`` into seconds."""
    if not text:
        raise ValueError(f"invalid duration: {text!r}")

    total = 0
    i = 0
    prev_order = 4  # higher than any valid unit order

    while i < len(text):
        # read integer
        start = i
        while i < len(text) and text[i].isdigit():
            i += 1
        if i == start:
            raise ValueError(f"invalid duration: {text!r}")
        value = int(text[start:i])

        # read unit
        if i >= len(text):
            raise ValueError(f"invalid duration: {text!r}")
        unit = text[i]
        if unit not in _UNITS:
            raise ValueError(f"invalid duration: {text!r}")
        order = _UNIT_ORDER[unit]
        if order >= prev_order:
            raise ValueError(f"invalid duration: {text!r}")
        prev_order = order

        total += value * _UNITS[unit]
        i += 1

    return total
